import fs from 'node:fs';
const base='data/veto_review_261021/';
const input=JSON.parse(fs.readFileSync(base+'b-input.json','utf8'));
const prior=JSON.parse(fs.readFileSync(base+'b-prior-read.json','utf8'));
const reviewed=new Map();
function book(i,veto,reason,scope,notes,extra={}) {
  if(reviewed.has(i))throw Error('duplicate '+i);
  const n=notes.split('|').map(s=>s.trim());
  if(n.length!==10)throw Error(`${i}: ${n.length} notes`);
  reviewed.set(i,{veto:veto?veto.split(','):[],reason,scope,notes:n,...extra});
}
